		IncludedUnits:      0,
		OveragePrice:       0,
		TaxRateBasisPoints: 0,
	}))
	must(s.Subscribe(accountID, "plan-1000", time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)))

